const fs = require('fs');
const path = require('path');

function listFiles(dir, allFiles = []) {
  const files = fs.readdirSync(dir);
  for (const file of files) {
    const name = path.join(dir, file);
    if (fs.statSync(name).isDirectory()) {
      listFiles(name, allFiles);
    } else {
      allFiles.push(name);
    }
  }
  return allFiles;
}

const rhythmPath = path.join(process.cwd(), 'rhythm');
if (fs.existsSync(rhythmPath)) {
  console.log(listFiles(rhythmPath).map(f => f.replace(rhythmPath + '/', '')).join('\n'));
} else {
  console.log('rhythm directory not found');
}

